script:
(function () {
  'use strict';
  // Lognormal price range around a fair-value estimate.
  //   total uncertainty s = sqrt(vol^2 x months/12 + valuation error^2)   (log terms, combined in quadrature)
  //   median price at horizon = your estimate E
  //   range at confidence c: E x exp(-z s) to E x exp(+z s), z = inverse normal of (1 + c) / 2
  //   P(price < x) = N((ln x - ln E) / s)
  // Inverse normal: Acklam's rational approximation (relative error < 1.2e-9);
  // normal CDF: Abramowitz & Stegun 26.2.17 (absolute error < 7.5e-8).
  // Verified: z(95%) = 1.959964, z(90%) = 1.644854, N(1.959964) = 0.975000.
  // Defaults ($150 price, $175 estimate, 12 months, 25% vol, 15% error, 95%): s = 0.291548,
  // range $98.83 to $309.89, P(below $150) = 29.85%, implied annual return 16.67%.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var LEVELS = [50, 68, 80, 90, 95, 99];
  var MOVES = [-30, -20, -10, 0, 10, 20, 30, 50];

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function pct(v, d) { return (v >= 0 ? '+' : '') + v.toFixed(d === undefined ? 1 : d) + '%'; }
  function prob(p) { p = p * 100; return p < 0.1 ? 'under 0.1%' : p > 99.9 ? 'over 99.9%' : p.toFixed(1) + '%'; }

  function normCdf(x) {
    var t = 1 / (1 + 0.2316419 * Math.abs(x));
    var d = 0.3989422804014327 * Math.exp(-x * x / 2);
    var p = d * t * (0.319381530 + t * (-0.356563782 + t * (1.781477937 + t * (-1.821255978 + t * 1.330274429))));
    return x > 0 ? 1 - p : p;
  }

  function normInv(p) {
    var a = [-39.69683028665376, 220.9460984245205, -275.9285104469687, 138.3577518672690, -30.66479806614716, 2.506628277459239];
    var b = [-54.47609879822406, 161.5858368580409, -155.6989798598866, 66.80131188771972, -13.28068155288572];
    var c = [-0.007784894002430293, -0.3223964580411365, -2.400758277161838, -2.549732539343734, 4.374664141464968, 2.938163982698783];
    var d = [0.007784695709041462, 0.3224671290700398, 2.445134137142996, 3.754408661907416];
    var q, r;
    if (p < 0.02425) {
      q = Math.sqrt(-2 * Math.log(p));
      return (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) / ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1);
    }
    if (p > 1 - 0.02425) {
      q = Math.sqrt(-2 * Math.log(1 - p));
      return -(((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) / ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1);
    }
    q = p - 0.5; r = q * q;
    return (((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r + a[5]) * q / (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1);
  }

  function model(price, estimate, months, vol, err) {
    var s = Math.sqrt(vol * vol * months / 12 + err * err);
    return {
      s: s,
      range: function (level) {
        var z = normInv((1 + level / 100) / 2);
        return { z: z, low: estimate * Math.exp(-z * s), high: estimate * Math.exp(z * s) };
      },
      below: function (x) { return s > 0 ? normCdf((Math.log(x) - Math.log(estimate)) / s) : (x > estimate ? 1 : 0); },
      annual: Math.pow(estimate / price, 12 / months) - 1
    };
  }

  function fill(bodyId, rows) {
    var body = document.getElementById(bodyId);
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (cells) {
      var tr = document.createElement('tr');
      cells.forEach(function (t) { var td = document.createElement('td'); td.textContent = t; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  function update() {
    var price = num('vcPrice'), estimate = num('vcEstimate'), months = num('vcMonths'),
        vol = num('vcVol'), err = num('vcErr'), level = num('vcLevel');
    var error = document.getElementById('vcError');
    var msg = '';
    if ([price, estimate, months, vol, err, level].some(isNaN)) msg = 'Fill in every field with a number.';
    else if (price <= 0 || estimate <= 0) msg = 'Current price and your estimate must be greater than zero.';
    else if (months < 1 || months > 120) msg = 'Use a time horizon from 1 to 120 months.';
    else if (vol < 0 || vol > 300 || err < 0 || err > 300) msg = 'Volatility and valuation error must be between 0% and 300%.';
    else if (vol === 0 && err === 0) msg = 'With zero volatility and zero error there is no range. Enter at least one above 0%.';
    else if (level < 50 || level > 99.9) msg = 'Use a confidence level from 50% to 99.9%.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    var m = model(price, estimate, months, vol / 100, err / 100);
    var r = m.range(level);
    set('vcLow', money.format(r.low));
    set('vcHigh', money.format(r.high));
    set('vcRangeLabel', level + '% range in ' + months + ' month' + (months === 1 ? '' : 's'));
    set('vcLowChange', pct((r.low / price - 1) * 100) + ' from today');
    set('vcHighChange', pct((r.high / price - 1) * 100) + ' from today');
    set('vcUpside', pct((estimate / price - 1) * 100));
    set('vcAnnual', isFinite(m.annual) ? pct(m.annual * 100) : '–');
    set('vcSpread', (m.s * 100).toFixed(1) + '%');
    set('vcLoss', prob(m.below(price)));
    set('vcGain25', prob(1 - m.below(price * 1.25)));
    set('vcSummary', 'Treating your estimate as the middle outcome, and if the volatility and error inputs are realistic, the price would end between ' +
      money.format(r.low) + ' and ' + money.format(r.high) + ' in about ' + level + ' out of 100 cases.');

    fill('vcLevels', LEVELS.map(function (L) {
      var x = m.range(L);
      return [L + '%', money.format(x.low), pct((x.low / price - 1) * 100), money.format(x.high), pct((x.high / price - 1) * 100)];
    }));
    fill('vcMoves', MOVES.map(function (mv) {
      var x = price * (1 + mv / 100);
      return [pct(mv, 0) + (mv === 0 ? ' (today)' : ''), money.format(x), prob(1 - m.below(x))];
    }));
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('vcForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
